// chat-view/components/web-search-indicator.ts
var WebSearchIndicator = class {
  constructor(eventBus, store) {
    this.eventBus = eventBus;
    this.store = store;
    this.statusEl = null;
    this.lastSupportsTools = false;
    this.lastConnected = false;
    this.unsubscribeStore = null;
    this.eventBus.on("model:changed", this.handleModelChanged.bind(this));
    this.eventBus.on("connection:changed", this.handleConnectionChanged.bind(this));
    this.eventBus.on("app:ready", this.initialize.bind(this));
    this.unsubscribeStore = this.store.subscribe(() => {
      const state = this.store.getState();
      const supportsTools = state.ui.currentModelSupportsTools;
      const isConnected = state.ui.isConnected;
      if (supportsTools !== this.lastSupportsTools || isConnected !== this.lastConnected) {
        this.lastSupportsTools = supportsTools;
        this.lastConnected = isConnected;
        this.updateDisplay();
      }
    });
  }
  initialize() {
    this.statusEl = document.getElementById("web-search-status");
    this.updateDisplay();
  }
  handleModelChanged(data) {
    setTimeout(() => this.updateDisplay(), 100);
  }
  handleConnectionChanged(data) {
    this.updateDisplay();
  }
  updateDisplay() {
    if (!this.statusEl)
      return;
    const state = this.store.getState();
    const supportsTools = state.ui.currentModelSupportsTools;
    const isConnected = state.ui.isConnected;
    const isEnabled = isConnected && supportsTools;
    this.statusEl.empty();
    const dot = this.statusEl.createSpan();
    dot.toggleClass("oa-dot-connected", isEnabled);
    dot.toggleClass("oa-dot-disconnected", !isEnabled);
    dot.textContent = "\u25CF";
    this.statusEl.appendText(isEnabled ? " Enabled" : " Disabled");
    this.statusEl.className = isEnabled ? "web-search-available" : "web-search-unavailable";
  }
  cleanup() {
    if (this.unsubscribeStore) {
      this.unsubscribeStore();
      this.unsubscribeStore = null;
    }
  }
};

